CREATE EXTENSION fuzzystrmatch WITH SCHEMA exposed;

CREATE FUNCTION exposed.person_name_words(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(word), ARRAY[]::text[])
    FROM regexp_split_to_table(lower(value), '[^[:alnum:]]+') AS word
    WHERE word <> ''
$$;

CREATE FUNCTION exposed.person_name_codes(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(exposed.soundex(word)), ARRAY[]::text[])
    FROM unnest(exposed.person_name_words(value)) AS word
$$;

CREATE FUNCTION exposed.person_name_distance(query text, candidate text) RETURNS integer
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
    WITH RECURSIVE words AS (
        SELECT exposed.person_name_words(query) AS wanted,
               exposed.person_name_words(candidate) AS available
    ), assignments(position, used, distance) AS (
        SELECT 0, ARRAY[]::integer[], 0 FROM words
        WHERE cardinality(wanted) > 0
          AND NOT EXISTS (SELECT FROM unnest(wanted) word WHERE char_length(word) > 255)
        UNION ALL
        SELECT a.position + 1, a.used || c.position, a.distance + d.distance
        FROM assignments a CROSS JOIN words w
        CROSS JOIN LATERAL unnest(w.available) WITH ORDINALITY AS c(word, position)
        CROSS JOIN LATERAL (
            SELECT CASE WHEN char_length(c.word) <= 255
                              AND char_length(w.wanted[a.position + 1]) <= 255
                        THEN exposed.levenshtein_less_equal(w.wanted[a.position + 1], c.word, 1)
                   END AS distance
        ) d
        WHERE a.position < cardinality(w.wanted)
          AND NOT c.position = ANY(a.used)
          AND exposed.soundex(w.wanted[a.position + 1]) = exposed.soundex(c.word)
          AND d.distance <= 1
    )
    SELECT min(distance) FROM assignments CROSS JOIN words
    WHERE position = cardinality(wanted)
$$;

CREATE INDEX members_person_name_codes ON exposed.members USING gin (exposed.person_name_codes(name));
CREATE INDEX funders_person_name_codes ON exposed.funders USING gin (exposed.person_name_codes(funder_name));
CREATE INDEX funder_aliases_person_name_codes ON exposed.funder_aliases USING gin (exposed.person_name_codes(funder_alias));
